/**
 * MIFECO WordPress Plugin — Template Registration + Stripe Integration
 * 
 * Place this in: /wp-content/plugins/mifeco-core/mifeco-core.php
 * Or include from: /wp-content/themes/YOUR_THEME/functions.php
 *
 * After activating, create WordPress pages with these slugs:
 *   /products/     → uses "Products Hub" template
 *   /hypatia/      → uses "Hypatia Pro" template
 *   /accelerator/  → uses "PM Accelerator" template
 *   /vibraengineer/→ uses "VibraEngineer" template
 *
 * Then set your WordPress Settings > Permalinks to "Post name"
 */

// =========================================================================
// 1. STRIPE INTEGRATION — Payment Links & Checkout
// =========================================================================

/**
 * MIFECO Stripe Configuration
 * 
 * Replace these with your actual Stripe Payment Link IDs.
 * Create payment links at: https://dashboard.stripe.com/payment-links
 *
 * For subscription products:
 *   1. Go to Stripe Dashboard > Products > Add Product
 *   2. Set pricing ($39/month, etc.)
 *   3. Create a Payment Link for each
 *   4. Copy the link ID (stripped from the full URL)
 *
 * Full link example: https://buy.stripe.com/28o5kF4qA3eL3Oc9AB
 * The ID is the last segment: 28o5kF4qA3eL3Oc9AB
 */
define('MIFECO_STRIPE_HYPATIA_FREE', 'https://buy.stripe.com/YOUR_HYPATIA_FREE_LINK');
define('MIFECO_STRIPE_HYPATIA_PRO', 'https://buy.stripe.com/YOUR_HYPATIA_PRO_LINK');
define('MIFECO_STRIPE_ACCELERATOR_FREE', 'https://buy.stripe.com/YOUR_ACCELERATOR_FREE_LINK');
define('MIFECO_STRIPE_ACCELERATOR_PRO', 'https://buy.stripe.com/YOUR_ACCELERATOR_PRO_LINK');
define('MIFECO_STRIPE_VIBRA_FREE', 'https://buy.stripe.com/YOUR_VIBRA_FREE_LINK');
define('MIFECO_STRIPE_VIBRA_PRO', 'https://buy.stripe.com/YOUR_VIBRA_PRO_LINK');
define('MIFECO_STRIPE_ENTERPRISE', 'https://buy.stripe.com/YOUR_ENTERPRISE_LINK');
define('MIFECO_STRIPE_SUITE', 'https://buy.stripe.com/YOUR_SUITE_LINK');

/**
 * Generate a Stripe checkout button
 */
function mifeco_stripe_button($price_id, $label = 'Subscribe Now', $class = 'btn-primary') {
    $link = '';
    switch ($price_id) {
        case 'hypatia-free':     $link = MIFECO_STRIPE_HYPATIA_FREE; break;
        case 'hypatia-pro':      $link = MIFECO_STRIPE_HYPATIA_PRO; break;
        case 'accelerator-free': $link = MIFECO_STRIPE_ACCELERATOR_FREE; break;
        case 'accelerator-pro':  $link = MIFECO_STRIPE_ACCELERATOR_PRO; break;
        case 'vibra-free':       $link = MIFECO_STRIPE_VIBRA_FREE; break;
        case 'vibra-pro':        $link = MIFECO_STRIPE_VIBRA_PRO; break;
        case 'enterprise':       $link = MIFECO_STRIPE_ENTERPRISE; break;
        case 'suite':            $link = MIFECO_STRIPE_SUITE; break;
        default:                 $link = MIFECO_STRIPE_ENTERPRISE;
    }
    return sprintf(
        '<a href="%s" target="_blank" rel="noopener" class="mifeco-btn %s" data-price="%s">%s</a>',
        esc_url($link), esc_attr($class), esc_attr($price_id), esc_html($label)
    );
}

/**
 * Shortcode: [mifeco_pricing product="hypatia" tier="pro"]
 * Usage in any WordPress page or post.
 */
add_shortcode('mifeco_pricing', function($atts) {
    $a = shortcode_atts(['product' => 'hypatia', 'tier' => 'pro', 'label' => ''], $atts);
    $labels = [
        'hypatia-free'      => 'Try Free',
        'hypatia-pro'       => 'Subscribe $39/mo',
        'accelerator-free'  => 'Launch Free',
        'accelerator-pro'   => 'Subscribe $39/mo',
        'vibra-free'        => 'Try Free',
        'vibra-pro'         => 'Subscribe $39/mo',
        'enterprise'        => 'Contact Sales',
        'suite'             => 'Buy Suite $99/mo',
    ];
    $key = $a['product'] . '-' . $a['tier'];
    $label = !empty($a['label']) ? $a['label'] : ($labels[$key] ?? 'Subscribe');
    return mifeco_stripe_button($key, $label);
});

// =========================================================================
// 2. PAGE TEMPLATE REGISTRATION
// =========================================================================

/**
 * Register MIFECO product page templates with WordPress.
 * After adding this, you'll see the templates in the Page Attributes dropdown
 * when creating/editing a page in wp-admin.
 */
add_filter('theme_page_templates', 'mifeco_register_templates');
function mifeco_register_templates($templates) {
    $templates['tpl-products.php']      = 'Products Hub';
    $templates['tpl-hypatia.php']       = 'Hypatia Pro Landing Page';
    $templates['tpl-accelerator.php']   = 'PM Accelerator Landing Page';
    $templates['tpl-vibraengineer.php'] = 'VibraEngineer Landing Page';
    return $templates;
}

/**
 * Load the correct template file when WordPress needs to render a page.
 * Template files must be in the theme root or plugin templates/ directory.
 */
add_filter('template_include', 'mifeco_load_template');
function mifeco_load_template($template) {
    $page_template_slug = get_page_template_slug(get_the_ID());

    $known_templates = [
        'tpl-products.php',
        'tpl-hypatia.php', 
        'tpl-accelerator.php',
        'tpl-vibraengineer.php',
    ];

    if (in_array($page_template_slug, $known_templates)) {
        // Look first in theme directory, then in plugin directory
        $theme_file = get_template_directory() . '/' . $page_template_slug;
        $plugin_file = plugin_dir_path(__FILE__) . 'templates/' . $page_template_slug;

        if (file_exists($theme_file)) {
            return $theme_file;
        } elseif (file_exists($plugin_file)) {
            return $plugin_file;
        }
    }

    return $template;
}

// =========================================================================
// 3. ENQUEUE MIFECO STYLES
// =========================================================================

add_action('wp_enqueue_scripts', 'mifeco_enqueue_styles');
function mifeco_enqueue_styles() {
    // Only load on MIFECO product pages
    if (!is_page_template(['tpl-products.php', 'tpl-hypatia.php', 'tpl-accelerator.php', 'tpl-vibraengineer.php'])) {
        return;
    }

    wp_enqueue_style('mifeco-products', get_template_directory_uri() . '/mifeco-products.css', [], '1.0.0');

    // Google Fonts
    wp_enqueue_style('mifeco-fonts', 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap', [], null);
}

// =========================================================================
// 4. HELPER: Live app URLs
// =========================================================================

function mifeco_app_url($product) {
    $urls = [
        'hypatia'     => 'https://project-hypatia-pro-1064319572465.us-west1.run.app',
        'accelerator' => 'https://project-management-accelerator-845075991286.us-west1.run.app',
        'vibraengineer' => 'https://vibraengineer-845075991286.us-west1.run.app',
    ];
    return $urls[$product] ?? '#';
}

// =========================================================================
// 5. ENQUEUE STRIPE.JS (for direct checkout, optional)
//    Uncomment to enable Stripe.js-based checkout instead of payment links.
// =========================================================================
// add_action('wp_enqueue_scripts', 'mifeco_stripe_js');
