//     wp_enqueue_script('stripe-js', 'https://js.stripe.com/v3/', [], null, true);
//     wp_enqueue_script('mifeco-checkout', get_template_directory_uri() . '/js/mifeco-checkout.js', ['stripe-js'], '1.0.0', true);
//     wp_localize_script('mifeco-checkout', 'MIFECO_STRIPE', [
//         'publishableKey' => 'pk_live_YOUR_STRIPE_PUBLISHABLE_KEY',
//         'hypatiaPro'  => 'price_YOUR_HYPATIA_PRO_PRICE_ID',
//         'acceleratorPro' => 'price_YOUR_ACCELERATOR_PRO_PRICE_ID',
