{"content": "/* ==========================================================================
   MIFECO Product Pages — Core Styles
   Place in: /wp-content/themes/YOUR_THEME/mifeco-products.css
   ========================================================================== */

/* Base */
.mifeco-section { max-width: 1100px; margin: 0 auto; padding: 80px 24px; }
.mifeco-section.wide { max-width: 1200px; }

/* Buttons */
.mifeco-btn {
  display: inline-block;
  padding: 14px 32px;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  transition: all 0.2s;
  cursor: pointer;
  font-family: inherit;
}
.mifeco-btn:hover { transform: translateY(-1px); }

/* Pricing Grid */
.mifeco-pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}
.mifeco-pricing-card {
  background: #fff;
  border-radius: 12px;
  padding: 32px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.08);
  border: 1px solid #e5e7eb;
}
.mifeco-pricing-card.featured {
  border: 2px solid var(--mifeco-accent, #6366f1);
  transform: scale(1.05);
  position: relative;
}
.mifeco-pricing-card.featured .badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--mifeco-accent, #6366f1);
  color: #fff;
  padding: 4px 20px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
}
.mifeco-pricing-card .price { font-size: 2rem; font-weight: 800; margin-bottom: 16px; }
.mifeco-pricing-card .price small { font-size: 0.9rem; font-weight: 400; }
.mifeco-pricing-card ul { list-style: none; padding: 0; margin: 0 0 24px; }
.mifeco-pricing-card ul li { padding: 6px 0; font-size: 0.9rem; }
.mifeco-pricing-card ul li:before { content: "✓ "; color: #22c55e; font-weight: 700; }

/* Use Cases */
.mifeco-uc-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.mifeco-uc-card { padding: 24px; border-radius: 12px; background: var(--bg-alt, #f8f9fc); text-align: left; }
.mifeco-uc-card .icon { font-size: 2rem; margin-bottom: 12px; }

/* FAQ */
.mifeco-faq { background: var(--bg-alt, #f8f9fc); }
.mifeco-faq-item {
  background: #fff;
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 12px;
  box-shadow: 0 4px 24px rgba(0,0,0,0.08);
}
.mifeco-faq-item h4 { margin-bottom: 8px; }

/* Responsive */
@media (max-width: 1024px) { .mifeco-uc-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 768px) { .mifeco-pricing-grid { grid-template-columns: 1fr; } .mifeco-pricing-card.featured { transform: none; } }
@media (max-width: 640px) { .mifeco-uc-grid { grid-template-columns: 1fr; } }
